import { Group, Image, Text, ActionIcon, rem } from "@mantine/core";
import { IconTrash } from "@tabler/icons-react";
import { useCart } from "../../context/CartContext";
import formatPrice from "../../lib/formatPrice";
import QuantitySelector from "../common/QuantitySelector";
import { products } from "../../data/products";

const CartItem = ({ item }) => {
  const { removeFromCart, updateQuantity } = useCart();

  if (!item) {
    return null;
  }

  const { productId, quantity, priceAtAdd } = item;

  // Get product info from products data
  const product = products.find((p) => p.id === productId) || null;

  if (!product) {
    return null;
  }

  const { name, image, stock } = product;

  const handleQuantityChange = (newQuantity) => {
    if (updateQuantity) {
      updateQuantity(productId, newQuantity);
    }
  };

  const handleRemove = () => {
    if (removeFromCart) {
      removeFromCart(productId);
    }
  };

  return (
    <Group position="apart" align="flex-start" spacing="md" mb="md">
      <Group spacing="sm" align="flex-start" style={{ flex: 1 }}>
        <Image
          src={image}
          alt={name}
          width={rem(80)}
          height={rem(80)}
          style={{ objectFit: "cover", borderRadius: rem(8) }}
        />
        <div>
          <Text weight={500} size="sm" lineClamp={2} mb={4}>
            {name}
          </Text>
          <Text weight={700} size="sm" color="success.6">
            {formatPrice(priceAtAdd)}
          </Text>
        </div>
      </Group>

      <Group spacing="sm" align="center">
        <QuantitySelector
          value={quantity}
          onChange={handleQuantityChange}
          min={1}
          max={stock}
        />
        <ActionIcon
          variant="subtle"
          color="error"
          size="sm"
          onClick={handleRemove}
          aria-label="Remove item"
        >
          <IconTrash size={rem(16)} />
        </ActionIcon>
      </Group>
    </Group>
  );
};

export default CartItem;

import { TextInput, Textarea, Select, Group, Text, Button, Card, rem, Box, Alert, Divider } from "@mantine/core";
import { IconCreditCard, IconCash, IconCheck } from "@tabler/icons-react";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useCart } from "../../context/CartContext";
import formatPrice from "../../lib/formatPrice";
import { products } from "../../data/products";

const CheckoutForm = () => {
  const navigate = useNavigate();
  const { cartItems, getCartTotal, clearCart } = useCart();
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const safeCartItems = Array.isArray(cartItems) ? cartItems : [];
  const total = getCartTotal ? getCartTotal() : 0;

  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    state: "",
    zipCode: "",
    country: "US",
    paymentMethod: "credit",
    cardNumber: "",
    cardExpiry: "",
    cardCvv: "",
  });

  const [errors, setErrors] = useState({});

  const validateForm = () => {
    const newErrors = {};

    if (!formData.firstName.trim()) {
      newErrors.firstName = "First name is required";
    }
    if (!formData.lastName.trim()) {
      newErrors.lastName = "Last name is required";
    }
    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "Invalid email format";
    }
    if (!formData.address.trim()) {
      newErrors.address = "Address is required";
    }
    if (!formData.city.trim()) {
      newErrors.city = "City is required";
    }
    if (!formData.state.trim()) {
      newErrors.state = "State is required";
    }
    if (!formData.zipCode.trim()) {
      newErrors.zipCode = "ZIP code is required";
    }

    if (formData.paymentMethod === "credit") {
      if (!formData.cardNumber.trim()) {
        newErrors.cardNumber = "Card number is required";
      } else if (!/^\d{16}$/.test(formData.cardNumber.replace(/\s/g, ""))) {
        newErrors.cardNumber = "Invalid card number";
      }
      if (!formData.cardExpiry.trim()) {
        newErrors.cardExpiry = "Expiry date is required";
      }
      if (!formData.cardCvv.trim()) {
        newErrors.cardCvv = "CVV is required";
      } else if (!/^\d{3,4}$/.test(formData.cardCvv)) {
        newErrors.cardCvv = "Invalid CVV";
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validateForm()) {
      setSubmitting(true);
      // Simulate processing
      setTimeout(() => {
        setSubmitting(false);
        setSubmitted(true);
        if (clearCart) {
          clearCart();
        }
        navigate("/order-confirmation");
      }, 1000);
    }
  };

  const handleChange = (field) => (value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Group spacing="xl" align="flex-start">
        <Box style={{ flex: 2 }}>
          <Card shadow="sm" padding="lg" radius="lg" mb="lg">
            <Text weight={600} size="lg" mb="md">
              Shipping Information
            </Text>

            <Group spacing="md" grow>
              <TextInput
                label="First Name"
                placeholder="John"
                value={formData.firstName}
                onChange={(e) => handleChange("firstName")(e.target.value)}
                error={errors.firstName}
                required
              />
              <TextInput
                label="Last Name"
                placeholder="Doe"
                value={formData.lastName}
                onChange={(e) => handleChange("lastName")(e.target.value)}
                error={errors.lastName}
                required
              />
            </Group>

            <TextInput
              label="Email"
              placeholder="john@example.com"
              value={formData.email}
              onChange={(e) => handleChange("email")(e.target.value)}
              error={errors.email}
              mt="md"
              required
            />

            <TextInput
              label="Phone"
              placeholder="+1 (555) 123-4567"
              value={formData.phone}
              onChange={(e) => handleChange("phone")(e.target.value)}
              mt="md"
            />

            <Textarea
              label="Address"
              placeholder="123 Main Street"
              value={formData.address}
              onChange={(e) => handleChange("address")(e.target.value)}
              error={errors.address}
              mt="md"
              required
            />

            <Group spacing="md" grow mt="md">
              <TextInput
                label="City"
                placeholder="New York"
                value={formData.city}
                onChange={(e) => handleChange("city")(e.target.value)}
                error={errors.city}
                required
              />
              <TextInput
                label="State"
                placeholder="NY"
                value={formData.state}
                onChange={(e) => handleChange("state")(e.target.value)}
                error={errors.state}
                required
              />
            </Group>

            <Group spacing="md" grow mt="md">
              <TextInput
                label="ZIP Code"
                placeholder="10001"
                value={formData.zipCode}
                onChange={(e) => handleChange("zipCode")(e.target.value)}
                error={errors.zipCode}
                required
              />
              <Select
                label="Country"
                data={[
                  { value: "US", label: "United States" },
                  { value: "CA", label: "Canada" },
                  { value: "UK", label: "United Kingdom" },
                ]}
                value={formData.country}
                onChange={handleChange("country")}
              />
            </Group>
          </Card>

          <Card shadow="sm" padding="lg" radius="lg">
            <Text weight={600} size="lg" mb="md">
              Payment Method
            </Text>

            <Group spacing="md" mb="md">
              <Button
                variant={formData.paymentMethod === "credit" ? "filled" : "outline"}
                color="brand"
                leftIcon={<IconCreditCard size={rem(18)} />}
                onClick={() => handleChange("paymentMethod")("credit")}
              >
                Credit Card
              </Button>
              <Button
                variant={formData.paymentMethod === "cash" ? "filled" : "outline"}
                color="brand"
                leftIcon={<IconCash size={rem(18)} />}
                onClick={() => handleChange("paymentMethod")("cash")}
              >
                Cash on Delivery
              </Button>
            </Group>

            {formData.paymentMethod === "credit" && (
              <>
                <TextInput
                  label="Card Number"
                  placeholder="1234 5678 9012 3456"
                  value={formData.cardNumber}
                  onChange={(e) => handleChange("cardNumber")(e.target.value)}
                  error={errors.cardNumber}
                  required
                />

                <Group spacing="md" grow mt="md">
                  <TextInput
                    label="Expiry Date"
                    placeholder="MM/YY"
                    value={formData.cardExpiry}
                    onChange={(e) => handleChange("cardExpiry")(e.target.value)}
                    error={errors.cardExpiry}
                    required
                  />
                  <TextInput
                    label="CVV"
                    placeholder="123"
                    value={formData.cardCvv}
                    onChange={(e) => handleChange("cardCvv")(e.target.value)}
                    error={errors.cardCvv}
                    required
                  />
                </Group>
              </>
            )}
          </Card>
        </Box>

        <Box style={{ flex: 1 }}>
          <Card shadow="sm" padding="lg" radius="lg" sticky>
            <Text weight={600} size="lg" mb="md">
              Order Summary
            </Text>

            {safeCartItems.length === 0 ? (
              <Text color="dimmed">No items in cart</Text>
            ) : (
              <>
                {safeCartItems.map((item) => {
                  const product = products.find((p) => p.id === item.productId) || null;
                  if (!product) return null;
                  return (
                    <Group key={item.productId} position="apart" mb="xs">
                      <Text size="sm" lineClamp={1}>
                        {product.name} × {item.quantity}
                      </Text>
                      <Text size="sm" weight={500}>
                        {formatPrice(item.priceAtAdd * item.quantity)}
                      </Text>
                    </Group>
                  );
                })}

                <Divider my="sm" />

                <Group position="apart" mb="sm">
                  <Text>Subtotal</Text>
                  <Text weight={500}>{formatPrice(total)}</Text>
                </Group>

                <Group position="apart" mb="sm">
                  <Text>Shipping</Text>
                  <Text weight={500} color="success.6">
                    {total >= 50 ? "Free" : formatPrice(9.99)}
                  </Text>
                </Group>

                <Divider my="sm" />

                <Group position="apart" mb="lg">
                  <Text weight={600} size="lg">
                    Total
                  </Text>
                  <Text weight={700} size="xl" color="success.6">
                    {formatPrice(total + (total >= 50 ? 0 : 9.99))}
                  </Text>
                </Group>
              </>
            )}

            <Button
              type="submit"
              rightIcon={<IconCheck size={rem(18)} />}
              fullWidth
              size="lg"
              loading={submitting}
              disabled={safeCartItems.length === 0}
            >
              Place Order
            </Button>
          </Card>
        </Box>
      </Group>
    </form>
  );
};

export default CheckoutForm;

import { Group, Chip, Slider, Text, Box, Button, rem } from "@mantine/core";
import { useState } from "react";

const FilterPanel = ({ categories, selectedCategory, onCategoryChange, priceRange, onPriceChange, onClearFilters }) => {
  const [priceRangeValue, setPriceRangeValue] = useState(priceRange || [0, 300]);

  const handlePriceChange = (values) => {
    setPriceRangeValue(values);
    if (onPriceChange) {
      onPriceChange(values);
    }
  };

  const handleClear = () => {
    setPriceRangeValue([0, 300]);
    if (onClearFilters) {
      onClearFilters();
    }
  };

  const safeCategories = Array.isArray(categories) ? categories : [];

  return (
    <Box>
      <Box mb="md">
        <Text size="sm" weight={500} mb="xs" c="dimmed">
          Categories
        </Text>
        <Chip.Group
          value={selectedCategory}
          onChange={onCategoryChange}
          multiple={false}
        >
          <Group spacing="xs" position="apart">
            {safeCategories.map((category) => (
              <Chip
                key={category}
                value={category}
                variant="filled"
                size="sm"
                radius="sm"
              >
                {category}
              </Chip>
            ))}
          </Group>
        </Chip.Group>
      </Box>

      <Box mb="md">
        <Text size="sm" weight={500} mb="xs" c="dimmed">
          Price Range
        </Text>
        <Slider
          min={0}
          max={300}
          step={10}
          value={priceRangeValue}
          onChange={handlePriceChange}
          label={(value) => `$${value}`}
          styles={{
            track: { marginTop: rem(10) },
          }}
        />
        <Group position="apart" mt="xs">
          <Text size="xs" c="dimmed">
            ${priceRangeValue[0]}
          </Text>
          <Text size="xs" c="dimmed">
            ${priceRangeValue[1]}
          </Text>
        </Group>
      </Box>

      <Button
        variant="subtle"
        color="gray"
        size="sm"
        onClick={handleClear}
        fullWidth
        mt="sm"
      >
        Clear Filters
      </Button>
    </Box>
  );
};

export default FilterPanel;

import { Group, ActionIcon, NumberInput, rem } from "@mantine/core";
import { IconMinus, IconPlus } from "@tabler/icons-react";

const QuantitySelector = ({ value, onChange, min = 1, max = 99, disabled = false }) => {
  const handleIncrement = () => {
    if (value < max && onChange) {
      onChange(value + 1);
    }
  };

  const handleDecrement = () => {
    if (value > min && onChange) {
      onChange(value - 1);
    }
  };

  const parseValue = (val) => {
    const numValue = typeof val === "number" ? val : Number(val) || min;
    return Math.max(min, Math.min(numValue, max));
  };

  return (
    <Group spacing="xs" align="center">
      <ActionIcon
        variant="outline"
        color="gray"
        size="sm"
        onClick={handleDecrement}
        disabled={disabled || value <= min}
        aria-label="Decrease quantity"
      >
        <IconMinus size={rem(14)} />
      </ActionIcon>
      <NumberInput
        value={value}
        onChange={(val) => {
          const clampedValue = parseValue(val);
          if (onChange) {
            onChange(clampedValue);
          }
        }}
        min={min}
        max={max}
        disabled={disabled}
        hideControls
        styles={{
          input: {
            width: rem(50),
            textAlign: "center",
            fontSize: "var(--mantine-font-size-sm)",
          },
        }}
        aria-label="Quantity"
      />
      <ActionIcon
        variant="outline"
        color="gray"
        size="sm"
        onClick={handleIncrement}
        disabled={disabled || value >= max}
        aria-label="Increase quantity"
      >
        <IconPlus size={rem(14)} />
      </ActionIcon>
    </Group>
  );
};

export default QuantitySelector;

import { Group, ActionIcon, Text, Indicator, Box, Container, rem } from "@mantine/core";
import { IconShoppingCart, IconMenu2 } from "@tabler/icons-react";
import { Link } from "react-router-dom";
import { useCart } from "../../context/CartContext";
import SearchBar from "../common/SearchBar";
import { useDisclosure } from "@mantine/hooks";

const Header = ({ onSearch, onCartClick }) => {
  const { getCartItemCount } = useCart();
  const itemCount = getCartItemCount();

  return (
    <Box
      component="header"
      style={{
        borderBottom: "1px solid var(--mantine-color-gray-3)",
        backgroundColor: "var(--mantine-color-white)",
        position: "sticky",
        top: 0,
        zIndex: 100,
      }}
    >
      <Container size="xl" h={60}>
        <Group position="apart" h="100%">
          <Group spacing="md">
            <Link
              to="/"
              style={{
                textDecoration: "none",
                color: "inherit",
              }}
            >
              <Text
                size="xl"
                weight={700}
                c="brand"
                style={{ cursor: "pointer" }}
              >
                ShopEasy
              </Text>
            </Link>
          </Group>

          <Box
            style={{
              flex: 1,
              maxWidth: rem(500),
              margin: "0 auto",
            }}
          >
            <SearchBar onSearch={onSearch} />
          </Box>

          <Group spacing="sm">
            <Indicator
              inline
              label={itemCount}
              size={16}
              disabled={itemCount === 0}
              styles={{
                indicator: {
                  fontSize: "var(--mantine-font-size-xs)",
                  fontWeight: 600,
                },
              }}
            >
              <ActionIcon
                variant="subtle"
                color="gray"
                size="lg"
                onClick={onCartClick}
                aria-label="Open cart"
              >
                <IconShoppingCart size={22} />
              </ActionIcon>
            </Indicator>
          </Group>
        </Group>
      </Container>
    </Box>
  );
};

export default Header;

const formatPrice = (price) => {
  const numericPrice = typeof price === "number" ? price : Number.parseFloat(price);
  if (Number.isNaN(numericPrice)) {
    return "$0.00";
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(numericPrice);
};

export default formatPrice;
